<script setup>import AdminNavigation from '@/Components/Admin/AdminNavigation.vue';import InputError from '@/Components/InputError.vue';import PortalLayout from '@/Layouts/PortalLayout.vue';import{Head,useForm}from'@inertiajs/vue3';const props=defineProps({ticket:Object,agents:Array});const manage=useForm({assigned_to:props.ticket.assigned_to||'',priority:props.ticket.priority,status:props.ticket.status});const reply=useForm({body:'',internal_note:false,attachments:[]});const send=()=>reply.post(route('admin.support.messages.store',props.ticket.uuid),{forceFormData:true,onSuccess:()=>reply.reset()});</script>
<template><Head :title="ticket.ticket_number"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="support"/></template><div v-if="$page.props.flash.success" class="success-message mb-4">{{ $page.props.flash.success }}</div><div class="mb-6"><p class="text-sm font-bold text-cyan-700">{{ ticket.ticket_number }}</p><h1 class="text-3xl font-bold">{{ ticket.subject }}</h1><p class="mt-2 text-slate-500">{{ ticket.customer.name }} · {{ ticket.product?.name || 'General' }} · opened {{ ticket.opened_at }}</p></div><div class="grid gap-6 lg:grid-cols-[1fr_320px]"><div><div class="space-y-4"><article v-for="message in ticket.messages" :key="message.uuid" class="rounded-2xl p-6 shadow-sm" :class="message.is_customer_visible?'bg-white':'border border-amber-200 bg-amber-50'"><div class="flex justify-between"><strong>{{ message.sender.name }} <span v-if="!message.is_customer_visible" class="text-xs text-amber-700">INTERNAL NOTE</span></strong><time class="text-sm text-slate-500">{{ message.created_at }}</time></div><p class="mt-3 whitespace-pre-line">{{ message.body }}</p><a v-for="file in message.attachments" :key="file.uuid" :href="route('support.attachments.show',file.uuid)" class="mr-3 mt-3 inline-block text-sm font-bold text-cyan-700">{{ file.original_name }}</a></article></div><form v-if="ticket.status!=='closed'" class="form-card mt-6" @submit.prevent="send"><label>{{ reply.internal_note?'Internal note':'Customer reply' }}<textarea v-model="reply.body" rows="5" required/><InputError :message="reply.errors.body"/></label><label class="flex items-center gap-2"><input v-model="reply.internal_note" type="checkbox"/> Internal note — hidden from customer</label><label>Attachments<input type="file" multiple @change="reply.attachments=Array.from($event.target.files)"/></label><button class="form-button">{{ reply.internal_note?'Add note':'Send reply' }}</button></form></div><aside><form class="form-card sticky top-4" @submit.prevent="manage.put(route('admin.support.update',ticket.uuid),{preserveScroll:true})"><h2 class="text-xl font-bold">Ticket controls</h2><label>Assigned agent<select v-model="manage.assigned_to"><option value="">Unassigned</option><option v-for="agent in agents" :key="agent.id" :value="agent.id">{{ agent.name }}</option></select></label><label>Priority<select v-model="manage.priority"><option v-for="v in ['low','normal','high','urgent']" :key="v">{{ v }}</option></select></label><label>Status<select v-model="manage.status"><option v-for="v in ['open','in_progress','waiting_customer','resolved','closed']" :key="v">{{ v }}</option></select></label><button class="form-button">Update ticket</button><dl class="space-y-2 text-sm"><div><dt class="text-slate-500">First response due</dt><dd>{{ ticket.first_response_due_at }}</dd></div><div><dt class="text-slate-500">Resolution due</dt><dd>{{ ticket.resolution_due_at }}</dd></div><div><dt class="text-slate-500">First responded</dt><dd>{{ ticket.first_responded_at || 'Pending' }}</dd></div><div v-if="ticket.sla_breached_at" class="text-red-700"><dt>SLA breached</dt><dd>{{ ticket.sla_breached_at }}</dd></div></dl></form></aside></div></PortalLayout></template>
